import { describe, expect, it } from "vitest";

import { qrShape } from "./qr-shape";

/**
 * What Supabase sends, copied from its QR drawer (goqrsvg on SVGo): no
 * viewBox, the colour in a style, and the quiet border left undrawn.
 * tests/db/owner-admin.test.ts checks a whole one from a real Supabase.
 */
const SUPABASE_QR = `<?xml version="1.0"?>
<!-- Generated by SVGo -->
<svg width="30" height="30"
     xmlns="http://www.w3.org/2000/svg"
     xmlns:xlink="http://www.w3.org/1999/xlink">
<rect x="12" y="12" width="3" height="3" style="fill:black;stroke:none" />
<rect x="15" y="12" width="3" height="3" style="fill:black;stroke:none" />
<rect x="12" y="15" width="3" height="3" style="fill:white;stroke:none" />
<rect x="15" y="15" width="3" height="3" style="fill:black;stroke:none" />
</svg>
`;

describe("qrShape", () => {
  it("keeps the dark squares as one path in a square the size of the drawing, quiet border and all", () => {
    expect(qrShape(SUPABASE_QR)).toEqual({ size: 30, path: "M12 12h6v3h-6zM15 15h3v3h-3z" });
  });

  it("reads the data: URL supabase-js hands back, plain or URL-encoded", () => {
    expect(qrShape(`data:image/svg+xml;utf-8,${SUPABASE_QR}`)).toEqual(qrShape(SUPABASE_QR));
    expect(qrShape(`data:image/svg+xml;utf-8,${encodeURIComponent(SUPABASE_QR)}`)).toEqual(qrShape(SUPABASE_QR));
  });

  it("also reads the colour from a fill attribute", () => {
    const attributes = SUPABASE_QR.replace(/style="fill:(\w+);stroke:none"/g, (_, colour: string) =>
      colour === "black" ? 'class="color" fill="#000000"' : 'class="bg-color" fill="#FFFFFF"',
    );
    expect(attributes).not.toContain("style=");
    expect(qrShape(attributes)).toEqual(qrShape(SUPABASE_QR));
  });

  it("works out the size from the squares when the drawing has none", () => {
    expect(qrShape(SUPABASE_QR.replace('width="30" height="30"', ""))?.size).toBe(30);
  });

  it("has nothing to draw without dark squares", () => {
    expect(qrShape('<svg width="30" height="30"></svg>')).toBeNull();
    expect(qrShape(SUPABASE_QR.replaceAll("fill:black", "fill:white"))).toBeNull();
  });
});
